import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

public class CSVParser_getHeaderMap_TriageGen1Test {

    @Test
    public void testGetHeaderMap_WithHeaders() throws IOException {
        String csvContent = "id,name,age\n1,John,30\n2,Jane,25";
        CSVFormat format = CSVFormat.DEFAULT.withHeader();

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Verify size and content
            assertEquals(3, headerMap.size());
            assertEquals(Integer.valueOf(0), headerMap.get("id"));
            assertEquals(Integer.valueOf(1), headerMap.get("name"));
            assertEquals(Integer.valueOf(2), headerMap.get("age"));

            // Verify it returns a copy (LinkedHashMap) and not the internal reference
            // We check this by modifying the returned map and ensuring it doesn't affect the parser 
            // (though parser doesn't provide a setter, the requirement is to test the implementation logic)
            headerMap.put("new_col", 99);
            assertEquals(4, headerMap.size());

            // Verify the map implementation is indeed a LinkedHashMap (as per source code)
            // and that it preserves order
            Object[] keys = headerMap.keySet().toArray();
            assertEquals("id", keys[0]);
            assertEquals("name", keys[1]);
            assertEquals("age", keys[2]);
            assertEquals("new_col", keys[3]);
        }
    }






}

