import java.io.Reader;
import java.io.StringReader;
import java.math.*;
import java.net.URL;
import java.nio.charset.Charset;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

public class CSVParser_getHeaderMap_TriageGen1Test {







    @Test
    public void testGetHeaderMap_ImmutabilityOfInternalState() throws IOException {
        String csvContent = "a,b";
        CSVFormat format = CSVFormat.DEFAULT.withHeader();

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            Map<String, Integer> firstCall = parser.getHeaderMap();

            // Modify the returned map
            firstCall.put("c", 3);

            Map<String, Integer> secondCall = parser.getHeaderMap();

            // The second call should not contain the element added to the first call
            // because the method returns a new LinkedHashMap instance
            assertEquals(2, secondCall.size());
            assertTrue(!secondCall.containsKey("c"));
            assertNotSame(firstCall, secondCall);
        }
    }
}
